import org.apache.commons.compress.archivers.tar.TarArchiveInputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveOutputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveInputStream;
import org.apache.commons.compress.archivers.zip.ZipArchiveOutputStream;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArchiveStreamFactory_createArchiveInputStream_TriageGen1Test {

    private ArchiveStreamFactory factory;

    @Before
    public void setUp() {
        factory = new ArchiveStreamFactory();
    }



















    @Test
    public void testCreateArchiveInputStream_TarAutoDetect() throws Exception {
        // Test the COMPRESS-117 branch: signatureLength >= 512 and tries to parse
        byte[] tarHeader = new byte[512];
        // Fill with something that looks like a tar header but might fail parsing
        // to trigger the catch block, or succeed to return TarArchiveInputStream.
        for (int i = 0; i < 512; i++) tarHeader[i] = 0;

        // We need a stream that provides 512 bytes
        InputStream in = new ByteArrayInputStream(tarHeader);

        try {
            factory.createArchiveInputStream(in);
        } catch (ArchiveException e) {
            // If it fails to parse as Tar, it throws ArchiveException "No Archiver found..."
            // which is expected behavior for garbage data.
            assertTrue(e.getMessage().contains("No Archiver found"));
        }
    }


}

